import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E9%9B%91%E8%8B%B1%E8%BE%9E%E9%83%8E.html","title":"雑英辞郎","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":2.12,"words":636},"filePathRelative":"雑英辞郎.md"}`),a={name:`雑英辞郎.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="雑英辞郎" tabindex="-1"><a class="header-anchor" href="#雑英辞郎"><span>雑英辞郎</span></a></h1><p>英辞郎のテキストデータが500円くらいで買えるので、それのビュワーアプリを作る事にする。<a href="./英和辞典.html">英和辞典</a>。<a href="./自作アプリ.html">自作アプリ</a></p><p>名前は雑な英辞郎アプリという事で雑英辞郎、と言う事にしよう。</p><ul><li><a href="https://github.com/Karino2DIYApp/ZatsuEijiro" target="_blank" rel="noopener noreferrer">Karino2DIYApp/ZatsuEijiro: Eijiro app for Android (not include data, you must buy from official site).</a></li></ul><h2 id="データの購入" tabindex="-1"><a class="header-anchor" href="#データの購入"><span>データの購入</span></a></h2><ul><li><a href="https://www.eijiro.jp/" target="_blank" rel="noopener noreferrer">英辞郎（えいじろう・EIJIRO）の最新情報</a> テキストデータが500円くらいで買える。</li></ul><h2 id="コンセプト" tabindex="-1"><a class="header-anchor" href="#コンセプト"><span>コンセプト</span></a></h2><ul><li>Androidの長期のメンテナンスが簡単なものを作る</li><li>たまにしか使わないので使い勝手は頑張らない</li><li>いろんな端末で使いたい</li><li>パフォーマンスよりデバッグのしやすさ優先</li></ul><h2 id="開発日記" tabindex="-1"><a class="header-anchor" href="#開発日記"><span>開発日記</span></a></h2><p>アプリ開発関連の記録を置いておく。</p><h3 id="assets下にのビルドでとりあえず動く-2026-10-25-日" tabindex="-1"><a class="header-anchor" href="#assets下にのビルドでとりあえず動く-2026-10-25-日"><span>assets下にのビルドでとりあえず動く 2026-10-25 (日)</span></a></h3><p>とりあえずPC側でsplitしたりlz4したりしたファイルをassets下に置いて、雑に動く。 単にTextViewに表示しているだけなのでセパレータとかも無いし他のエントリへのリンクとかも一切処理していないが、まぁまぁ十分だな、これ。</p><p>ほとんど自分で書かずにgeminiに書いてもらった。</p><p>インポートはそのうち必要になったら書こう。</p><hr><h2 id="ファイルの仕様検討-2026-10-25-日" tabindex="-1"><a class="header-anchor" href="#ファイルの仕様検討-2026-10-25-日"><span>ファイルの仕様検討 2026-10-25 (日)</span></a></h2><p>とりあえず先頭のローマ字何文字かでファイルに分けて、それを圧縮した感じのを適当にルックアップする感じにしたい。</p><p>どのくらいに分割したらいいかなどをPCで検討する。</p><h3 id="テキストデータを眺める" tabindex="-1"><a class="header-anchor" href="#テキストデータを眺める"><span>テキストデータを眺める</span></a></h3><p>一行あたり1エントリで見出し語のあとはコロンがある。 他のエントリを参照してほしいものは、コロンのあとに「＜ーXXXX＞」が半角で書いてある（XXXXに該当する見出しが書いてある）。</p><p>イディオムも全て一行で入っている。</p><p>見出しの後には空白二つが入り品詞が入り、その後コロンで意味が続く。 複数の意味がある場合は品詞のあとにハイフンで数字が振られる。</p><p>発音記号などはあればその後に単独の行で入る。</p><h3 id="フォーマットの検討" tabindex="-1"><a class="header-anchor" href="#フォーマットの検討"><span>フォーマットの検討</span></a></h3><p>思ったよりサイズが小さいので、まずはシンプルなデータで不足が無いか見てみる。</p><p>見出しのインデックスで1ファイル、そのほかはまずは先頭文字ごとに24ファイルに分割していこう。 これでは大きなばらつきが出るとは思うが、それで圧縮してどのくらいかを検討したい。大きな文字があったら先頭2文字で分割、小さすぎる分にはまぁいいかな、と思っている。</p><p>圧縮フォーマットはとりあえずlz4にしてみる。 全体を圧縮したらlz4で78.6MB。24に分かれてくれれば1ファイル4MB以下になるが、ちょっと大きいね。最終的には先頭2文字になりそうだが、まずは先頭1文字で分割する所から始める。</p><p>とりあえずnodejsでcopilotに書かせる。</p><h3 id="コンバートはアプリでやる方がいいか" tabindex="-1"><a class="header-anchor" href="#コンバートはアプリでやる方がいいか"><span>コンバートはアプリでやる方がいいか</span></a></h3><p>コンバードはPC側でも簡単に出来るが、コンバートしたものをどうやってアプリに入れるかを考えると意外と面倒な事に気づく。</p><p>assetsに置いてビルドするのが一番カンタンだが、これだとapkを公開できなくなる（データが入っちゃうので）。 置いてビルドしてね、って感じにしてもいいのだが、端末乗り換えやタブレット買った時などにいちいちapkのビルド環境をもう一度作るのはかったるいし、apkを持ち回るのもかったるい。</p><p>やりたいのは単に先頭の文字でsplitだから、アプリでやってもいいかもなぁ。 apkにはデータは含めずに、初回に外からデータを渡してdata下に保存する感じでいいか。</p><p>zipはたかだが50MBくらいなので、これを端末で読み込ませて、見出しごとに分けてlz4で圧縮してdata下に保存、としよう。</p><h3 id="pcでの分割データの調査" tabindex="-1"><a class="header-anchor" href="#pcでの分割データの調査"><span>PCでの分割データの調査</span></a></h3><p>aa.txt, ab.txtなどに分割してみる。さらに一文字のものはa.txtとか、aより前のは0before.txt、zより後のはzzafter.txtとした。</p><p>nushellで</p><div class="language-nu line-numbers-mode" data-highlighter="prismjs" data-ext="nu"><pre><code class="language-nu"><span class="line">~/source/MySource/EijiroConv/split&gt; ls *.txt | get size | math avg</span>
<span class="line">295.0 kB</span>
<span class="line">~/source/MySource/EijiroConv/split&gt; ls *.txt | get size | math max</span>
<span class="line">6.6 MB</span>
<span class="line">~/source/MySource/EijiroConv/split&gt; ls *.txt | get size | math min</span>
<span class="line">30 B</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>との事。</p><div class="language-nu line-numbers-mode" data-highlighter="prismjs" data-ext="nu"><pre><code class="language-nu"><span class="line"> ls *.txt | where size &gt;= 2MiB</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>は12個。</p><p>一番大きいco.txtをlz4したら、2.8MBに。ちょっと大きいなぁ。</p><h3 id="大きいものは4分割までする" tabindex="-1"><a class="header-anchor" href="#大きいものは4分割までする"><span>大きいものは4分割までする</span></a></h3><ul><li>2分割で一通り作る</li><li>1MiB以上は3文字に分割</li><li>1MiB以上は4文字に分割</li></ul><p>とする事にした。4分割までするとhave.txtが最大で2.6MBで、1MiB以上は7つだが、だいたい1MiBちょっと。これでいいだろう。</p><div class="language-nu line-numbers-mode" data-highlighter="prismjs" data-ext="nu"><pre><code class="language-nu"><span class="line">&gt; ls *.txt | where size &gt;= 1MiB</span>
<span class="line">╭───┬──────────┬──────┬────────┬────────────────╮</span>
<span class="line">│ # │   name   │ type │  size  │    modified    │</span>
<span class="line">├───┼──────────┼──────┼────────┼────────────────┤</span>
<span class="line">│ 0 │ get.txt  │ file │ 1.2 MB │ 20 seconds ago │</span>
<span class="line">│ 1 │ give.txt │ file │ 1.1 MB │ 20 seconds ago │</span>
<span class="line">│ 2 │ have.txt │ file │ 2.6 MB │ 20 seconds ago │</span>
<span class="line">│ 3 │ in.txt   │ file │ 1.4 MB │ 23 seconds ago │</span>
<span class="line">│ 4 │ inte.txt │ file │ 1.1 MB │ 20 seconds ago │</span>
<span class="line">│ 5 │ make.txt │ file │ 1.2 MB │ 20 seconds ago │</span>
<span class="line">│ 6 │ take.txt │ file │ 1.0 MB │ 20 seconds ago │</span>
<span class="line">│ 7 │ with.txt │ file │ 1.2 MB │ 20 seconds ago │</span>
<span class="line">╰───┴──────────┴──────┴────────┴────────────────╯</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="インデックスの試行錯誤" tabindex="-1"><a class="header-anchor" href="#インデックスの試行錯誤"><span>インデックスの試行錯誤</span></a></h3><p>見出し語だけをリストアップしたindex.txtを作ってみた。 サイズは61.4MB。うーん、全部オンメモリでは重いか。</p><p>中身の方と同じにしてもいいんだが、まぁそこまで分けなくてもいいかなぁ。</p><p>先頭一文字で分けてみた所、s.txtは6MB。ちょっと大きいか。</p><p>先頭2文字で分けるとだいたい1MB以下で、1MB以上は10ファイル、一番大きくて2.2MBなのでこのくらいならいいか。</p><h3 id="暫定分割方法" tabindex="-1"><a class="header-anchor" href="#暫定分割方法"><span>暫定分割方法</span></a></h3><ul><li>0before.txt, zzzafter.txt</li><li>a.txt, aa.txt, ab.txt ..., zy.txt zz.txt <ul><li>一文字はa.txtになる事に注意</li><li>1MiB以上はaba.txt, abb.txt...と3文字にする</li><li>3文字で1MiB以上だったら4文字に分割</li><li>4文字以上は分割しない</li></ul></li></ul><p>をsplitディレクトリに、indexをスプリットしたものをsplit_indexに置く。</p><p>ファイルはlz4で圧縮する（ファイル名は0before.txt.lz4などとする）</p>`,54)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};